/**
 * Live result from the food survey, shown inline in the homepage bio.
 *
 * Reads data/survey-stats.json - the same file the gated results page uses,
 * regenerated by .github/workflows/update-survey-data.yml. Only the `fruits`
 * question surfaces here, because the bullet it sits in already asks it.
 *
 * The wrapper span stays hidden until every field resolves, so a failed fetch
 * leaves the original sentence reading exactly as it did before.
 *
 * The clause is composed here as plain text rather than assembled from markup:
 * answers originate as free text in a Google Form, so they never touch
 * innerHTML, and a tie needs a different sentence shape than a single winner.
 *
 * Markup: the spans in _pages/about.md.
 */
(function () {
  'use strict';

  var DATA_URL = '/data/survey-stats.json';

  /* Responses the cleaning pass in process_survey_data.py couldn't map onto a
     real fruit. They survive in the file as literal keys, so filter by name. */
  var NON_ANSWERS = ['null', 'none', 'n/a', ''];

  /* Past this many tied leaders the sentence stops being worth reading. */
  var MAX_TIED_LEADERS = 3;

  function isAnswer(key) {
    return NON_ANSWERS.indexOf(key.trim().toLowerCase()) === -1;
  }

  /* "mango" / "mango and apple" / "mango, apple, and pear" */
  function formatList(names) {
    if (names.length === 1) return names[0];
    if (names.length === 2) return names[0] + ' and ' + names[1];
    return names.slice(0, -1).join(', ') + ', and ' + names[names.length - 1];
  }

  function buildClause(fruits) {
    var keys = Object.keys(fruits).filter(isAnswer);
    if (!keys.length) return null;

    var total = keys.reduce(function (sum, key) { return sum + fruits[key]; }, 0);
    if (!total) return null;

    var lead = keys.reduce(function (max, key) {
      return fruits[key] > max ? fruits[key] : max;
    }, 0);

    var winners = keys.filter(function (key) { return fruits[key] === lead; });
    if (winners.length > MAX_TIED_LEADERS) return null;

    var share = Math.round((lead / total) * 100) + '%';
    var names = formatList(winners.map(function (name) { return name.toLowerCase(); }));

    return winners.length === 1
      ? 'so far ' + share + ' of ' + total + ' people say ' + names
      : 'so far ' + names + ' are tied at ' + share + ' each, of ' + total + ' people';
  }

  function render(data) {
    if (!data || !data.fruits) return;

    var clause = buildClause(data.fruits);
    if (!clause) return;

    document.getElementById('fruit-verdict-text').textContent = clause;
    document.getElementById('fruit-verdict').hidden = false;
  }

  document.addEventListener('DOMContentLoaded', function () {
    if (!document.getElementById('fruit-verdict')) return;

    fetch(DATA_URL)
      .then(function (r) {
        if (!r.ok) throw new Error(DATA_URL + ' returned ' + r.status);
        return r.json();
      })
      .then(render)
      .catch(function (error) {
        // The bullet reads fine without the number, so leave it hidden.
        console.warn('Survey teaser unavailable:', error.message);
      });
  });
})();
